        {
          $match: {
            $expr: { $lt: ["$Enrollment", "$$avg_Enrollment"] }
          }
        },
        {
          $unwind: "$basketball_match"
        },
        {
          $project: {
            _id: 0,
            Team_Name: "$basketball_match.Team_Name"
          }
        }
      ],
      as: "Docs1"
    }
  },
  {
    $unwind: "$Docs1"
  },
  {
    $project: {
      Team_Name: "$Docs1.Team_Name",
      _id: 0
    }
  }
]);

